def logo_img(height_px: int = 30, extra_style: str = "") -> str:
    """An <img> tag for the logo at `height_px` high (width follows the aspect ratio)."""
    return (f'<img class="kslogo" alt="Keysight" src="{LOGO_DATA_URI}" height="{height_px}" '
            f'style="height:{height_px}px;width:auto;display:block;{extra_style}">')
